let state=loadState(),auth=null,role=null,session={},storageOK=true,loginEmail='';
const params=new URLSearchParams(location.search);
if(params.get('next')==='admin')sessionStorage.setItem('buyme-login-return','admin');
let route=location.hash.slice(1)||(params.get('deal')?'deal:'+params.get('deal'):'market');
function syncAuth(){auth=Auth.currentAuth(state);role=auth?.role||null;session=auth?{[role]:auth.id}:{};}
function requireLogin(target=route){sessionStorage.setItem('buyme-login-return',target);go('login');}
function afterLogin(){syncAuth();if(role==='member'){mergeGuestCart(state,auth.id);persist();}const target=sessionStorage.getItem('buyme-login-return');sessionStorage.removeItem('buyme-login-return');if(role==='admin'){location.href='./admin.html';return;}route=target&&Auth.allowedRoute(target,role)?target:role==='provider'?'dashboard':'market';history.replaceState(null,'','#'+route);render();window.scrollTo(0,0);}
let categoriesExpanded=false,checkoutDraft={},checkoutFailed=false;
const cartOwner=()=>role==='member'?auth.id:'guest';
const checkoutToken=()=>checkoutDraft.token||(checkoutDraft.token=(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2)));
let filter={q:'',category:'',subcategory:'',region:'',min:'',sort:'recommended'},dealFilter='',dealSearch='',providerScope='all',dealTab='overview',selectedThread='',messageMode='direct',modal=null,drafts={},reviewSaved=null,lastFocus=null;
const $=q=>document.querySelector(q),me=()=>role==='member'?state.members.find(x=>x.id===session.member):state.providers.find(x=>x.id===session.provider);
const myDeals=()=>auth&&['member','provider'].includes(role)?state.deals.filter(d=>role==='member'?d.userId===auth.id:d.providerId===auth.id):[];
const badge=(v,type='deal')=>`<span class="badge ${v}"><i></i>${esc((type==='pay'?PL:type==='offer'?{active:'Aktiv',pending:'Wartet auf Freigabe',paused:'Pausiert',rejected:'Zurückgewiesen'}:DL)[v])}</span>`;
const button=(label,action,cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,to,cls='btn secondary')=>`<a class="${cls}" href="#${to}">${label}</a>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(){try{saveState(state);storageOK=true;}catch{storageOK=false;toast('Browserspeicher voll oder gesperrt. Diese Änderung bleibt nur für die Sitzung erhalten.');}}
function go(r){if(route===r){render();return;}location.hash=r;}
function switchRole(next){if(next===role){if(role==='admin')location.href='./admin.html';else go(role==='provider'?'dashboard':'market');return;}if(next==='admin'){location.href='./admin.html';return;}go(next==='provider'?'register-provider':'register');}

function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${role==='provider'?'DEIN ANBIETERBEREICH':'DEIN BUYME'}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,sub,art='wallet'){return `<div class="stat"><span class="stat-label">${label}${icon(art)}</span><strong>${value}</strong><small>${sub}</small></div>`;}
function render(){syncAuth();
 if(!Auth.allowedRoute(route,role)){if(!auth){sessionStorage.setItem('buyme-login-return',route);route='login';history.replaceState(null,'','#login');}else if(role==='admin'){location.href='./admin.html';return;}else{route=role==='provider'?'dashboard':'market';history.replaceState(null,'','#'+route);}}
 const focus=document.activeElement?.id,pos=document.activeElement?.selectionStart,u=me(),w=role==='member'?M.walletSummary(state,auth.id):null;
 const nav=role==='member'?[['market','Marktplatz','grid'],['deals','Meine Deals','deal'],['wallet','Wallet','wallet'],['orders','Bestellungen','cart'],['messages','Nachrichten','chat'],['reviews','Bewertungen','check'],['profile','Mein Profil','users']]:role==='provider'?[['dashboard','Übersicht','grid'],['offers','Meine Angebote','deal'],['deals','Meine Deals','users'],['budget','Budget','wallet'],['orders','Bestellungen','cart'],['messages','Nachrichten','chat'],['reviews','Bewertungen','check'],['profile','Firmenprofil','building'],['market','Marktplatz','grid']]:[['market','Marktplatz','grid'],['how','So funktioniert BuyMe','help']];
 $('#app').innerHTML=`<div class="demo-strip"><div><span class="private-dot"></span><strong>Privater Testbetrieb</strong><span class="demo-strip-text">Fiktive Angebote · keine echten Zahlungen</span></div><a href="#test-access">Testzugänge</a></div>
 <header class="site-header"><div class="header-inner"><a href="#${role==='provider'?'dashboard':'market'}" class="brand"><img class="brand-logo" src="./assets/buyme-logo-light.svg" width="239" height="68" alt="BuyMe"></a><span class="header-label">Geld statt Punkte.</span><div class="auth-header-actions">${(!role||role==='member')?`<a href="#cart" class="cart-header" aria-label="Warenkorb">${icon('cart')}<span>Warenkorb</span><b>${cartCount(state,cartOwner())}</b></a>`:''}${auth?`<a href="${role==='admin'?'./admin.html':'#profile'}" class="signed-account"><span class="avatar">${initial(u?.name||'Admin')}</span><span>${esc(u?.name||'Administration')}<small>${role==='provider'?'Anbieter':role==='admin'?'Administration':'Mitglied'}</small></span></a>${role==='member'?`<a href="#wallet" class="wallet-chip">${icon('wallet')} ${money(w.available)}</a>`:role==='provider'?`<a href="#offer-new" class="btn primary small">${icon('plus')} Angebot erstellen</a>`:`<a href="./admin.html" class="btn primary small">Admin Cockpit</a>`}<button class="btn text small" data-action="logout">Abmelden</button>`:`<a href="#register-provider" class="provider-entry">Für Anbieter</a><a href="#login" class="btn secondary">Anmelden</a><a href="#register" class="btn primary">Registrieren</a>`}</div></div></header>
 <nav class="main-nav" aria-label="Hauptnavigation"><div>${nav.map(([r,l,i])=>`<a href="#${r}" class="${route===r||(r==='deals'&&route.startsWith('deal:'))?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}${l}${r==='deals'?`<span>${myDeals().length}</span>`:''}</a>`).join('')}</div></nav>
 ${!storageOK?'<div class="save-warning">Speichern im Browser derzeit eingeschränkt. Bitte wichtige Testdaten exportieren.</div>':''}${role==='provider'&&!u?.verified?'<div class="save-warning">Dein Anbieterprofil wird geprüft. Nach Freigabe durch die Administration kannst du Budget hinterlegen und Angebote erstellen.</div>':''}
 <main id="main" tabindex="-1">${renderPage()}</main><footer><div><a class="brand small-brand" href="#market"><img class="brand-logo" src="./assets/buyme-logo-light.svg" width="239" height="68" alt="BuyMe"></a><p>Anbieter gewinnen Kunden. Du erhältst echtes Geld.</p><span>Privater Testbetrieb · Fiktive Daten · Konten und Teststand nur in diesem Browser</span></div><div><a href="#how">So funktioniert BuyMe</a><a href="#register-provider">Anbieter werden</a><a href="./admin.html">Administration</a><a href="#test-access">Testzugänge & Hinweise</a></div></footer>${legalFooter()}`;
 renderModal();if(focus&&document.getElementById(focus)){const el=document.getElementById(focus);el.focus();if(typeof pos==='number'&&el.setSelectionRange)try{el.setSelectionRange(pos,pos);}catch{}}
}

function renderPage(){if(isLegalRoute(route))return legalPage(route,state,auth);if(['login','register','register-provider'].includes(route)){if(auth)return `<div class="panel auth-panel already-signed"><h1>Du bist angemeldet</h1><p>${esc(me()?.name||'Administration')}</p><a class="btn primary" href="${role==='admin'?'./admin.html':role==='provider'?'#dashboard':'#deals'}">Zu deinem Bereich</a><button class="btn secondary" data-action="logout">Abmelden</button></div>`;return authPage(route,loginEmail);}if(route==='test-access')return testAccessPage();if(route==='how')return howPage();if(route==='security')return securityPage();if(route==='cart')return cartPage(state,cartOwner(),{member:role==='member'});if(route==='checkout'){checkoutToken();return checkoutPage(state,auth.id,{draft:checkoutDraft,failure:checkoutFailed});}if(route==='orders'||route.startsWith('order:'))return ordersPage(state,role,auth.id,route.startsWith('order:')?route.slice(6):null);if(route==='market')return marketplace();if(route.startsWith('offer:'))return offerDetail(route.slice(6));if(route.startsWith('provider:'))return providerProfile(route.slice(9));if(route.startsWith('deal:'))return dealDetail(route.slice(5));if(route==='deals')return dealsPage();if(route==='messages')return messagesPage();if(route==='reviews')return reviewsPage();if(route==='profile')return profilePage();if(role==='provider'){if(route==='offers')return providerOffers();if(route==='offer-new'||route.startsWith('offer-edit:'))return offerForm(route.startsWith('offer-edit:')?route.slice(11):null);if(route==='budget')return budgetPage();return providerDashboard();}if(route==='wallet')return walletPage();return marketplace();}
function offerCard(o){const p=state.providers.find(x=>x.id===o.providerId),available=M.offerAvailable(state,o)>=o.cashback+M.feeFor(o.cashback);return `<article class="offer-card ${o.purchase?'purchase-card':''}"><a href="#offer:${o.id}" class="offer-art art-${o.art}" aria-label="Angebot ansehen">${o.purchase?productArt(o):`<span class="art-orbit"></span>${icon(o.art)}<span class="art-label">${esc(categoryName(o.category))}</span>`}<span class="art-cashback">${money(o.cashback)}<small>Cashback</small></span></a><div class="offer-card-body"><a href="#provider:${p.id}" class="provider-line"><span class="provider-initial">${initial(p.name)}</span>${userText(p.name)}${icon('shield')}</a><a href="#offer:${o.id}" class="offer-title">${userText(o.title)}</a><div class="offer-subcategory">${esc(classificationLabel(o))}</div><p>${userText(o.description)}</p><div class="offer-meta"><span>${o.purchase?money(o.purchase.unitCents/100):userText(o.price)}</span><span>${o.purchase?icon('cart')+'Kaufangebot':icon('pin')+userText(o.region)}</span></div><div class="offer-card-bottom"><span class="${available?'funds-ok':'text-amber'}">${icon(available?'check':'clock')}${available?'Prämienbudget gedeckt':'Budget ausgeschöpft'}</span><a href="#offer:${o.id}">${o.purchase?'Auswählen':'Details'} ${icon('arrow')}</a></div></div></article>`;}

function subcategoryOptions(category,selected='',all=false){const values=subcategoriesFor(category);return opt('',all?'Alle Unterkategorien':values.length?'Bitte Unterkategorie wählen':'Keine Unterkategorien hinterlegt',selected)+values.map(v=>opt(v,v,selected)).join('');}
function subcategoryNavigation(){const values=subcategoriesFor(filter.category);if(!values.length)return '';return `<div class="subcategory-navigation" aria-label="Unterkategorien: ${esc(filter.category)}"><div class="subcategory-heading"><strong>${esc(filter.category)}</strong><span>${values.length} Unterkategorien</span></div><div class="subcategory-chips"><button data-subcategory="" class="${!filter.subcategory?'selected':''}" aria-pressed="${!filter.subcategory}">Alle</button>${values.map(v=>`<button data-subcategory="${esc(v)}" class="${filter.subcategory===v?'selected':''}" aria-pressed="${filter.subcategory===v}">${esc(v)}</button>`).join('')}</div></div>`;}
function marketplace(){const offers=M.availableOffers(state,filter),hasFilter=filter.q||filter.category||filter.subcategory||filter.region||filter.min;return `${!hasFilter?`<section class="hero"><div class="hero-copy"><div class="eyebrow">DEIN MARKTPLATZ FÜR ECHTE GELDPRÄMIEN</div><h1>Deine Entscheidung.<br><span>Dein Cashback.</span></h1><p>Finde Angebote, die zu dir passen. Unternehmen belohnen deinen bestätigten Abschluss mit echtem Geld – direkt in deiner BuyMe-Wallet.</p><div class="hero-actions"><button data-action="scroll-offers" class="btn primary">Angebote entdecken ${icon('arrow')}</button><button class="btn text" data-action="help">So funktioniert BuyMe</button></div><div class="hero-trust"><span>${icon('check')} Kostenlos für Mitglieder</span><span>${icon('shield')} Geprüfte Anbieter im Testbetrieb</span></div></div><div class="hero-showcase"><div class="floating-tag">${icon('check')} Deine Entscheidung lohnt sich</div><div class="showcase-card"><div class="showcase-top"><span class="provider-initial">NM</span><span>Nordlicht Mobil<small>Telekommunikation</small></span>${icon('shield')}</div><div class="showcase-art">${icon('mobil')}<span>60<span>GB</span></span><i>5G FLEX</i></div><div class="showcase-amount"><span>Deine Geldprämie<strong>160 €</strong></span><span class="showcase-tick">${icon('check')}</span></div><a href="#offer:OF-119" class="btn primary">Angebot ansehen ${icon('arrow')}</a></div><div class="floating-note">${icon('wallet')} Geld statt Punkte.<small>Transparent. Nachvollziehbar. BuyMe.</small></div></div></section><section class="how-strip" aria-label="So funktioniert BuyMe"><div><span>01</span><p><strong>Angebot entdecken</strong>Passenden Anbieter auswählen</p></div><div><span>02</span><p><strong>Abschluss bestätigen</strong>Bedingungen erfüllen und Nachweis hinterlegen</p></div><div><span>03</span><p><strong>Geldprämie erhalten</strong>Freigegebenes Cashback auszahlen lassen</p></div></section>`:''}
 <section id="market-results" class="market-section"><div class="section-heading"><div><div class="eyebrow">ANGEBOTE, DIE SICH FÜR DICH LOHNEN</div><h2>${filter.subcategory?esc(filter.subcategory):filter.category?esc(filter.category):'Entdecke deinen nächsten Deal'}</h2></div><span class="results-count">${offers.length} ${offers.length===1?'Angebot':'Angebote'}</span></div>${categoryBrowser(filter.category,categoriesExpanded)}${subcategoryNavigation()}<div class="market-filters"><label class="search-field">${icon('search')}<input id="offer-search" aria-label="Angebote suchen" placeholder="Angebot, Anbieter oder Unterkategorie suchen …" value="${esc(filter.q)}"></label><label class="region-field">${icon('pin')}<input id="region-search" aria-label="Region suchen" placeholder="Ort oder Region" value="${esc(filter.region)}"></label><select id="category-filter" aria-label="Hauptkategorie filtern">${opt('','Alle Hauptkategorien',filter.category)}${CATEGORIES.map(c=>opt(c,c,filter.category)).join('')}</select><select id="subcategory-filter" aria-label="Unterkategorie filtern" ${!subcategoriesFor(filter.category).length?'disabled':''}>${subcategoryOptions(filter.category,filter.subcategory,true)}</select><select id="offer-sort" aria-label="Angebote sortieren">${opt('recommended','Neueste Angebote',filter.sort)}${opt('cashback','Höchstes Cashback',filter.sort)}${opt('low','Niedrigstes Cashback',filter.sort)}</select></div>${hasFilter?`<div class="active-filters">${filter.category?esc(filter.category):'Suche und Filter aktiv'}${filter.subcategory?' › '+esc(filter.subcategory):''} <button data-action="clear-filters">Alle zurücksetzen</button></div>`:''}<p class="legal-inline-note"><a href="#transparency">Wie werden Angebote sortiert und Bewertungen geprüft?</a></p><div class="offer-grid">${offers.map(offerCard).join('')}</div>${!offers.length?empty('Keine passenden Angebote','Ändere deine Suche oder setze die Filter zurück.',button('Filter zurücksetzen','clear-filters')):''}</section>`;}
function offerDetail(id){const o=state.offers.find(x=>x.id===id);if(!o)return empty('Angebot nicht gefunden','Wähle ein Angebot aus dem Marktplatz.',link('Zum Marktplatz','market'));if(o.purchase)return purchaseOfferDetail(state,o,{role,active:M.availableOffers(state).some(x=>x.id===id)&&M.offerAvailable(state,o)>=o.cashback+M.feeFor(o.cashback)});const p=state.providers.find(x=>x.id===o.providerId),existing=role==='member'&&state.deals.find(d=>d.offerId===id&&d.userId===auth.id&&d.status!=='cancelled'),available=M.availableOffers(state).some(x=>x.id===id)&&M.offerAvailable(state,o)>=o.cashback+M.feeFor(o.cashback);return `<div class="crumb"><a href="#market">Marktplatz</a>${icon('chevron')}<span>${esc(categoryName(o.category))}</span>${o.subcategory?icon('chevron')+'<span>'+esc(o.subcategory)+'</span>':''}</div><section class="offer-detail"><div class="offer-detail-main"><div class="detail-art art-${o.art}"><div class="art-orbit"></div>${icon(o.art)}<span>${esc(categoryName(o.category))}</span></div><div class="panel detail-copy"><h2>Das bietet dir ${userText(p.name)}</h2><p>${userText(o.description)}</p><h3>Deine Prämienbedingungen</h3><p>${userText(o.conditions)}</p><div class="info-note">${icon('help')}<span>Der Kauf oder Vertrag wird mit dem Anbieter abgeschlossen. Im Prototyp wird nur der Dealablauf mit der zugehörigen Prämie simuliert.</span></div><h3>So kommt dein Cashback an</h3><ol class="plain-steps"><li>Deal anlegen und Abschlussreferenz hinterlegen.</li><li>Anbieter prüft und bestätigt den Abschluss.</li><li>Admin prüft die Frist und gibt das Cashback frei.</li><li>Auszahlung in deiner Wallet anfordern und im Admin simulieren.</li></ol></div></div><aside class="offer-summary"><div class="panel sticky-summary"><a class="provider-line" href="#provider:${p.id}"><span class="provider-initial">${initial(p.name)}</span>${userText(p.name)}${icon('shield')}</a><h1>${userText(o.title)}</h1><div class="detail-price">${userText(o.price)}</div><div class="cashback-block"><span>Deine Geldprämie</span><strong>${money(o.cashback)}</strong><small>Kein Abzug der BuyMe-Servicegebühr</small></div><dl class="summary-facts"><div><dt>Region</dt><dd>${userText(o.region)}</dd></div><div><dt>Angebot bis</dt><dd>${date(o.validUntil+'T12:00:00Z')}</dd></div><div><dt>Prüffrist laut Demo</dt><dd>${o.payoutDays} Tage</dd></div><div><dt>Budgetstatus</dt><dd>${available?'Gedeckt':'Nicht verfügbar'}</dd></div></dl>${!auth?button('Anmelden und Deal starten '+icon('arrow'),'login-to-deal','primary full',`data-id="${o.id}" ${!available?'disabled':''}`):role==='member'?existing?link('Zu deinem Deal '+icon('arrow'),'deal:'+existing.id,'btn primary full'):button('Deal starten '+icon('arrow'),'accept','primary full',`data-id="${o.id}" ${!available||me().status!=='active'?'disabled':''}`):`<div class="info-note">Um einen Deal anzunehmen, melde dich mit einem Mitgliedskonto an.</div>`}<p class="fineprint">Fiktives Beispielangebot. Kein echter Vertrag, keine echte Bestellung.</p></div></aside></section>`;}
function providerProfile(id){const p=state.providers.find(x=>x.id===id);if(!p)return empty('Anbieter nicht gefunden','Bitte wähle einen Anbieter im Marktplatz.');const reviews=M.reviewsAbout(state,'provider',id),offers=M.availableOffers(state).filter(o=>o.providerId===id);return `<div class="crumb"><a href="#market">Marktplatz</a>${icon('chevron')}Anbieterprofil</div><section class="panel public-provider"><span class="provider-avatar">${icon(p.art)}</span><div><span class="eyebrow">${p.verified?'VERIFIZIERTER ANBIETER':'ANBIETER · PRÜFUNG OFFEN'}</span><h1>${userText(p.name)}</h1><p>${userText(p.description)}</p><span class="provider-region">${icon('pin')}${userText(p.region)} · ${reviews.length} ${reviews.length===1?'Bewertung':'Bewertungen'}</span></div></section><div class="section-heading"><h2>Angebote von ${userText(p.name)}</h2><span class="results-count">${offers.length} Angebote</span></div><div class="offer-grid">${offers.map(offerCard).join('')}</div><div class="section-heading"><h2>Erfahrungen mit dem Anbieter</h2></div><div class="review-grid">${publicRatingPanel(state,p.id)}</div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('search')}<h2>${title}</h2><p>${text}</p>${action}</div>`;}
function nextStep(d){if(d.status==='cancelled')return 'Storniert · keine Auszahlung';if(d.payment==='paid')return 'Ausgezahlt · Bewertungen im Deal';if(d.payment==='failed')return 'Auszahlungsfehler mit BuyMe klären';if(d.payment==='processing')return 'Zahlungsdienst verarbeitet die Auszahlung';if(d.payment==='released')return 'Cashback verfügbar · Auszahlung anfordern';if(d.providerReview?.correction?.status==='open')return 'Mitglied: Nachweis ergänzen';if(['requested','review'].includes(d.status)&&M.providerStage(d).key==='new')return 'Anbieter: Angebotsannahme prüfen';if(d.status==='requested')return 'Mitglied: Nachweis hinterlegen';if(d.status==='review')return 'Anbieter: Abschluss prüfen und freigeben';if(d.status==='confirmed')return 'Admin: Frist prüfen und Abschluss dokumentieren';return 'Admin: Cashback freigeben';}
function dealsPage(){const own=myDeals(),scopes=[['all','Alle Deals',own.length],['new','Neue Annahmen',own.filter(d=>M.providerStage(d).key==='new').length],['active','In Bearbeitung',own.filter(d=>['proof','correction','ready'].includes(M.providerStage(d).key)).length],['ready','Zur Freigabe',own.filter(d=>M.providerStage(d).key==='ready').length],['confirmed','Anbieterfreigabe',own.filter(d=>M.providerStage(d).key==='confirmed').length]],ds=own.filter(d=>(role!=='provider'||providerScope==='all'||(providerScope==='active'?['proof','correction','ready'].includes(M.providerStage(d).key):M.providerStage(d).key===providerScope))&&(!dealFilter||d.status===dealFilter)&&(!dealSearch||[d.id,d.offer,d.user,d.provider,d.providerReview?.reference||''].some(v=>v.toLowerCase().includes(dealSearch.toLowerCase()))));return heading(role==='member'?'Meine Deals':'Meine Kunden-Deals',role==='member'?'Jeder Abschluss mit eigenem Verlauf, Nachrichten und Cashbackstatus.':'Angebotsannahmen prüfen, Vorgänge bearbeiten und Abschlüsse zur Cashback-Prüfung freigeben.',role==='member'?link('Angebote entdecken '+icon('arrow'),'market'):link('Angebot erstellen '+icon('plus'),'offer-new'))+`${role==='provider'?`<div class="provider-deal-scopes" aria-label="Anbieterbearbeitung filtern">${scopes.map(([key,label,count])=>`<button data-provider-scope="${key}" class="${providerScope===key?'selected':''}" aria-pressed="${providerScope===key}">${label}<b>${count}</b></button>`).join('')}</div>`:''}<div class="deal-filters"><label class="search-field">${icon('search')}<input id="deal-search" aria-label="Meine Deals durchsuchen" placeholder="Dealnummer, Angebot oder Beteiligte suchen …" value="${esc(dealSearch)}"></label><select id="deal-filter" aria-label="Dealstatus filtern">${opt('','Alle Status',dealFilter)}${Object.entries(DL).map(([k,v])=>opt(k,v,dealFilter)).join('')}</select></div><div class="deal-list">${ds.map(d=>dealRow(d)).join('')}</div>${!ds.length?empty('Keine Deals in dieser Ansicht','Passe die Bearbeitungsansicht, Suche oder Statusfilter an.') : ''}`;}
function dealRow(d){return `<article class="panel deal-row"><div class="deal-row-icon art-${state.providers.find(p=>p.id===d.providerId)?.art||'shop'}">${icon(categoryIcon(d.category))}</div><div class="deal-row-content"><div class="deal-row-top"><span class="mono">${d.id}</span>${badge(d.status)}${badge(d.payment,'pay')}</div><h2><a href="#deal:${d.id}">${userText(d.offer)}</a></h2><p>${userText(role==='member'?d.provider:d.user)} · ${date(d.created)}</p>${role==='provider'?`<span class="workflow-state ${M.providerStage(d).key}">${M.providerStage(d).label}</span>`:''}<div class="next-step">${icon('clock')}${nextStep(d)}</div></div><div class="deal-row-end"><strong>${money(d.cashback)}</strong><small>Cashback für das Mitglied</small><a href="#deal:${d.id}" class="btn secondary small">${role==='provider'&&['requested','review'].includes(d.status)?'Prüfen & bearbeiten':'Details öffnen'} ${icon('arrow')}</a></div></article>`;}
function dealDetail(id){const d=myDeals().find(x=>x.id===id);if(!d)return empty('Deal nicht verfügbar','Dieser Deal gehört nicht zu deinem angemeldeten Konto.',link('Zur Dealübersicht','deals'));const p=state.providers.find(x=>x.id===d.providerId),tickets=state.tickets.filter(t=>t.dealId===id&&t.role===(role==='member'?'user':'provider'));return `<div class="crumb"><a href="#deals">${role==='member'?'Meine Deals':'Kunden-Deals'}</a>${icon('chevron')}<span>${d.id}</span></div>${heading(userText(d.offer),'Angenommen am '+date(d.created)+' · '+esc(role==='member'?d.provider:d.user))}<div class="deal-detail-grid"><div><div class="panel deal-status-panel"><div class="deal-status-top">${badge(d.status)}${badge(d.payment,'pay')}<strong>${money(d.cashback)} Cashback</strong></div><div class="status-steps">${['requested','review','confirmed','completed'].map((v,i)=>`<div class="${d.status!=='cancelled'&&['requested','review','confirmed','completed'].indexOf(d.status)>=i?'done':''}"><span>${d.status!=='cancelled'&&['requested','review','confirmed','completed'].indexOf(d.status)>i?icon('check'):i+1}</span><small>${DL[v]}</small></div>`).join('')}</div><div class="deal-classification">${icon('grid')}${esc(classificationLabel(d))}</div><div class="next-step prominent">${icon('clock')}<span><strong>Nächster Schritt</strong>${nextStep(d)}</span></div></div>${purchasePanel(state,d,role)}${providerWorkflowPanel(state,d,role)}<div class="detail-tabs">${[['overview','Überblick'],['chat','Nachrichten ('+d.messages.length+')'],['history','Verlauf'],['reviews','Bewertungen ('+M.reviewsForDeal(state,id).length+')'],['support','BuyMe-Support'+(tickets.length?' ('+tickets.length+')':'')]].map(([v,l])=>`<button data-tab="${v}" class="${dealTab===v?'active':''}" aria-pressed="${dealTab===v}">${l}</button>`).join('')}</div><div class="panel detail-tab-body">${dealTab==='chat'?directConversation(d):dealTab==='history'?timeline(d):dealTab==='support'?supportPanel(d,tickets):dealTab==='reviews'?dealReviewsPanel(state,d,role,me().id,{draft:drafts['review-entry']||{},saved:reviewSaved}):dealOverview(d)}</div></div><aside><div class="panel side-summary"><div class="eyebrow">DEINE VEREINBARUNG</div><h3>${userText(d.provider)}</h3><dl class="summary-facts"><div><dt>Deal-ID</dt><dd>${d.id}</dd></div><div><dt>Vertragsreferenz</dt><dd>${d.contract}</dd></div><div><dt>Preis beim Anbieter</dt><dd>${esc(d.snapshot?.price||'Siehe Angebot')}</dd></div><div><dt>Prämie</dt><dd>${money(d.cashback)}</dd></div><div><dt>Budgetdeckung</dt><dd>${d.funded?'Gedeckt':'Noch offen'}</dd></div></dl><p class="fineprint">Angebotsdaten wurden bei der Annahme gespeichert und bleiben für diesen Deal erhalten.</p><a href="#provider:${d.providerId}" class="btn secondary full">Anbieterprofil ${icon('arrow')}</a></div><div class="panel side-summary"><h3>Bewertungen</h3><p>Bewertungen von Mitglied und Anbieter zu diesem Deal.</p><button class="btn secondary full" data-tab="reviews">Bewertungen ansehen</button>${M.canReview(state,d,role,me().id)?button(role==='member'?'Anbieter bewerten':'Mitglied bewerten','review','primary full',`data-id="${id}"`):''}</div>${role==='member'&&['requested','review','confirmed'].includes(d.status)?`<button class="cancel-link" data-action="cancel" data-id="${id}">Deal stornieren</button>`:''}</aside></div>`;}
function dealOverview(d){return `<h2>Gespeicherte Angebotskonditionen</h2><p>${userText(d.snapshot?.description||d.offer)}</p><h3>Prämienbedingungen</h3><p>${esc(d.snapshot?.conditions||'Bestätigung des Abschlusses und erfüllte Prämienbedingungen.')}</p><div class="proof-box"><div>${icon('deal')}<strong>Nachweis zum Abschluss</strong></div>${d.proof?`<p><span class="funds-ok">${icon('check')} Nachweis hinterlegt</span><br><span class="mono">${esc(d.proof.reference)}</span><br><small>${date(d.proof.at)} · Demo-Referenz, keine echte Datei</small></p>`:'<p>Der Anbieter benötigt eine Bestell- oder Vertragsreferenz für die Prüfung.</p>'}${role==='member'&&['requested','review'].includes(d.status)?button(d.proof?'Nachweis ergänzen':'Nachweis hinterlegen','proof','primary small',`data-id="${d.id}"`):''}</div>${role==='member'&&d.payment==='released'?link('Zur Wallet und Auszahlung '+icon('arrow'),'wallet','btn primary'):''}${role==='provider'&&!d.funded&&d.status!=='cancelled'?`<div class="info-note">Die Budgetzuordnung fehlt noch. ${button('Budgetdeckung simulieren','fund-deal','secondary small',`data-id="${d.id}"`)}</div>`:''}${role==='provider'&&d.status==='confirmed'?`<div class="info-note">${icon('check')}<span>Deine Bestätigung ist dokumentiert. Der Admin kann nun die Fristprüfung simulieren und den Deal abschließen.</span></div>`:''}<h3>Abrechnung</h3><dl class="summary-facts"><div><dt>Cashback für das Mitglied</dt><dd>${money(d.cashback)}</dd></div><div><dt>Servicegebühr des Anbieters</dt><dd>${money(d.fee)} · Demoannahme 10 %</dd></div><div><dt>Gesamtbelastung Anbieter</dt><dd>${money(d.cashback+d.fee)}</dd></div></dl><p class="fineprint">Die 10 % sind eine Beispielannahme für den Test. Die tatsächliche BuyMe-Gebühr wird hiermit nicht festgelegt.</p>`;}
function timeline(d){return `<h2>Der gesamte Deal im Verlauf</h2><ol class="timeline">${[...d.events].filter(e=>e.title!=='Interne Notiz hinzugefügt').sort((a,b)=>b.at.localeCompare(a.at)).map(e=>`<li><span>${icon(e.kind==='payment'?'wallet':e.kind==='message'?'chat':'check')}</span><div><small>${date(e.at)} · ${time(e.at)} · ${esc(e.actor)}</small><h3>${esc(e.title)}</h3><p>${esc(e.detail)}</p></div></li>`).join('')}</ol>`;}
function directConversation(d){return `<div class="conversation-title"><h2>${role==='member'?'Nachricht an '+esc(d.provider):'Nachricht an '+esc(d.user)}</h2><span class="mono">${d.id}</span></div><div class="chat-messages">${d.messages.map(m=>messageBubble(m,d)).join('')||'<div class="chat-empty">Stelle deine Frage direkt zum Deal. Die Unterhaltung bleibt mit diesem Vorgang verknüpft.</div>'}</div><form data-form="direct" data-id="${d.id}" class="composer"><label for="direct-text" class="sr-only">Nachricht zum Deal</label><textarea id="direct-text" name="text" required maxlength="3000" placeholder="Deine Nachricht zu diesem Deal …">${esc(drafts['direct-'+d.id]||'')}</textarea><div><small>Demo-Nachricht · nur im Browser gespeichert</small><button class="btn primary small" type="submit">Nachricht speichern ${icon('send')}</button></div></form>`;}
function messageBubble(m,d,support=false){const myFrom=role==='member'?'user':'provider',mine=m.from===myFrom;return `<div class="chat-bubble ${mine?'mine':''}"><div><strong>${m.from==='admin'?'BuyMe Support':m.from==='user'?esc(d.user):esc(d.provider)}</strong><time>${date(m.at)} · ${time(m.at)}</time></div><p>${userText(m.text)}</p></div>`;}
function supportPanel(d,tickets){return `<div class="section-heading"><h2>Rückfragen an BuyMe</h2>${button('Neue Rückfrage '+icon('plus'),'support','secondary small',`data-id="${d.id}"`)}</div><p class="muted">Der Admin sieht deine Rückfrage mit Deal- und Zahlungsstatus und kann im Cockpit antworten.</p>${tickets.map(t=>`<div class="support-thread"><div class="conversation-title"><h3>${userText(t.subject)}</h3><span class="badge ${t.status==='open'?'review':'completed'}">${t.id} · ${t.status==='open'?'Offen':'Erledigt'}</span></div>${t.messages.filter(m=>m.from!=='internal').map(m=>messageBubble(m,d,true)).join('')}<form data-form="support-reply" data-id="${t.id}" class="composer"><label class="sr-only" for="support-${t.id}">Antwort an BuyMe</label><textarea id="support-${t.id}" name="text" required maxlength="3000" placeholder="Deine Antwort an BuyMe …"></textarea><div><small>${t.status==='resolved'?'Eine Antwort öffnet die Anfrage wieder.':'Antwort bleibt mit diesem Deal verknüpft.'}</small><button class="btn primary small">Antwort speichern</button></div></form></div>`).join('')||'<div class="chat-empty">Noch keine Supportanfrage zu diesem Deal.</div>'}`;}
function messagesPage(){const ds=myDeals(),support=state.tickets.filter(t=>t.role===(role==='member'?'user':'provider')&&ds.some(d=>d.id===t.dealId));let chosen=ds.find(d=>d.id===selectedThread)||ds.find(d=>d.messages.length)||ds[0];if(chosen)selectedThread=chosen.id;return heading('Nachrichten','Jede Unterhaltung und jede Rückfrage gehört zu einem konkreten Deal.')+`<div class="detail-tabs"><button data-message-mode="direct" class="${messageMode==='direct'?'active':''}">Mitglieder & Anbieter</button><button data-message-mode="support" class="${messageMode==='support'?'active':''}">BuyMe-Support (${support.length})</button></div>${messageMode==='support'?`<div class="panel">${ds.filter(d=>support.some(t=>t.dealId===d.id)).map(d=>`<h3 class="support-deal-heading"><a href="#deal:${d.id}">${d.id} · ${userText(d.offer)}</a></h3>${supportPanel(d,support.filter(t=>t.dealId===d.id))}`).join('')||empty('Noch keine Rückfragen','Erstelle eine Supportanfrage direkt in einem deiner Deals.',link('Meine Deals','deals'))}</div>`:`<div class="message-layout"><aside class="panel thread-list">${ds.map(d=>`<button data-thread="${d.id}" class="${chosen?.id===d.id?'selected':''}"><span>${userText(role==='member'?d.provider:d.user)}</span><strong>${userText(d.offer)}</strong><small>${d.id} · ${d.messages.length} Nachrichten</small></button>`).join('')||'<p class="muted">Deine Deal-Unterhaltungen erscheinen hier.</p>'}</aside><div class="panel">${chosen?`<a class="linked-deal" href="#deal:${chosen.id}">${icon('deal')} ${chosen.id} · ${esc(chosen.offer)} ${icon('arrow')}</a>${directConversation(chosen)}`:empty('Noch keine Unterhaltung','Nimm ein Angebot an, um mit einem Anbieter zu sprechen.',link('Angebote entdecken','market'))}</div></div>`}`;}
function walletPage(){const w=M.walletSummary(state,session.member),ds=myDeals();return heading('Meine Wallet','Dein Cashback. Jeder Betrag mit einem nachvollziehbaren Deal verknüpft.',button('Auszahlung anfordern '+icon('arrow'),'payout','primary',w.available<=0?'disabled':''))+`<section class="stats four">${stat('Vorgemerkt',money(w.pending),'Noch kein bestätigtes Guthaben','clock')}${stat('Verfügbar',money(w.available),'Freigegeben · bereit zur Auszahlung')}${stat('In Auszahlung',money(w.processing),'Vom Demo-Zahlungsdienst in Bearbeitung','arrow')}${stat('Ausgezahlt',money(w.paid),'Erfolgreich abgeschlossene Demo-Auszahlungen','check')}</section>${w.failed?`<div class="alert-box">${icon('alert')}<span>${money(w.failed)} konnten nicht ausgezahlt werden. Öffne den betreffenden Deal und kläre den Fehler mit BuyMe.</span></div>`:''}<div class="info-note">${icon('lock')}<span>Die Wallet ist eine Übersicht im Prototyp. Keine echte Kontoverbindung, keine echten Geldbewegungen. Die Servicegebühr trägt der Anbieter zusätzlich zu deinem Cashback.</span></div><section class="panel"><div class="section-heading"><h2>Deine Cashback-Historie</h2><span class="results-count">${ds.length} Vorgänge</span></div><div class="table-scroll"><table><thead><tr><th>Deal / Angebot</th><th>Cashback</th><th>Zahlungsstatus</th><th>Nächster Schritt</th><th>Beleg</th></tr></thead><tbody>${ds.map(d=>`<tr><td><a href="#deal:${d.id}"><strong>${d.id}</strong><small>${userText(d.offer)}</small></a></td><td class="amount">${money(d.cashback)}</td><td>${badge(d.payment,'pay')}</td><td class="table-note">${nextStep(d)}</td><td>${d.payment==='paid'?`<button class="text-btn" data-action="receipt" data-id="${d.id}">${icon('download')} Testbeleg</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>${!ds.length?empty('Deine erste Prämie wartet','Starte mit einem Angebot aus dem Marktplatz.',link('Angebote entdecken','market')):''}</section>`;}
function providerDashboard(){const p=me(),os=state.offers.filter(o=>o.providerId===p.id),ds=myDeals(),review=ds.filter(d=>['requested','review'].includes(d.status)),used=os.reduce((a,o)=>a+M.offerUsed(state,o.id),0);return heading('Hallo, '+userText(p.name)+'.','Gewinne Kunden mit Angeboten, die sich für beide Seiten lohnen.',link('Neues Angebot '+icon('plus'),'offer-new'))+`<section class="stats four">${stat('Aktive Angebote',os.filter(o=>o.status==='active').length,'Von der Administration freigegeben','deal')}${stat('Kunden-Deals',ds.length,'Alle Abschlüsse im Überblick','users')}${stat('Annahmen & Nachweise',review.length,'Warten auf deine Bearbeitung','clock')}${stat('Reserviert / verbraucht',money(used),'Cashback und beispielhafte Servicegebühr','wallet')}</section><section class="provider-banner"><div><div class="eyebrow">DEIN NÄCHSTER SCHRITT</div><h2>${review.length?review.length+' Abschlüsse warten auf deine Prüfung':'Bereit für neue Kunden?'}</h2><p>${review.length?'Prüfe die Nachweise und bestätige erfolgreiche Abschlüsse.':'Erstelle ein neues Angebot und lasse es im Admin Cockpit freigeben.'}</p></div>${link(review.length?'Nachweise prüfen '+icon('arrow'):'Angebot erstellen '+icon('plus'),review.length?'deals':'offer-new','btn white')}</section><div class="two-col"><section class="panel"><div class="section-heading"><h2>Letzte Kunden-Deals</h2><a href="#deals">Alle ansehen ${icon('arrow')}</a></div>${ds.slice(0,4).map(d=>`<a class="compact-deal" href="#deal:${d.id}"><span><strong>${userText(d.user)}</strong><small>${d.id} · ${userText(d.offer)}</small></span>${badge(d.status)}<strong>${money(d.cashback)}</strong>${icon('chevron')}</a>`).join('')||'<p class="muted">Deine ersten Kunden-Deals erscheinen hier.</p>'}</section><section class="panel budget-teaser"><div class="eyebrow">DEIN KAMPAGNENBUDGET</div><h2>${money(p.credit)}</h2><p>Demo-Guthaben für neue Angebote und Budgeterhöhungen.</p><a href="#budget" class="btn secondary">Budget verwalten ${icon('arrow')}</a><div class="fineprint">Bestehende Angebote haben eigene Budgets. Reservierungen bleiben direkt dem jeweiligen Deal zugeordnet.</div></section></div>`;}
function providerOffers(){const os=state.offers.filter(o=>o.providerId===session.provider);return heading('Meine Angebote','Erstellen, zur Freigabe einreichen und bestehende Kampagnen steuern.',link('Neues Angebot '+icon('plus'),'offer-new'))+`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Angebot</th><th>Cashback</th><th>Status</th><th>Budget / noch frei</th><th>Deals</th><th>Aktionen</th></tr></thead><tbody>${os.map(o=>`<tr><td><a href="#offer:${o.id}"><strong>${userText(o.title)}</strong><small>${o.id} · ${esc(classificationLabel(o))}</small></a>${o.status==='rejected'?`<small class="text-red">${esc(o.moderationNote)}</small>`:''}</td><td class="amount">${money(o.cashback)}</td><td>${badge(o.status,'offer')}</td><td><strong>${money(o.budget)}</strong><small>${money(M.offerAvailable(state,o))} frei</small></td><td>${state.deals.filter(d=>d.offerId===o.id).length}</td><td><div class="table-actions"><a class="text-btn" href="#offer-edit:${o.id}">Bearbeiten</a>${['active','paused'].includes(o.status)?`<button class="text-btn" data-action="toggle-offer" data-id="${o.id}">${o.status==='active'?'Pausieren':'Aktivieren'}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${!os.length?empty('Dein erstes Angebot','Erstelle ein Angebot mit Prämie und klaren Bedingungen.',link('Angebot erstellen','offer-new')):''}</section>`;}
function budgetPage(){const p=me(),os=state.offers.filter(o=>o.providerId===p.id),total=os.reduce((a,o)=>a+o.budget,0),used=os.reduce((a,o)=>a+M.offerUsed(state,o.id),0);return heading('Budget & Abrechnung','Angebotsbudgets, Reservierungen und die Prämien deiner Mitglieder.',button('Demo-Guthaben aufladen '+icon('plus'),'topup'))+`<section class="stats three">${stat('Freies Demo-Guthaben',money(p.credit),'Für neue Angebote und Budgeterhöhungen')}${stat('Kampagnenbudgets',money(total),'Bereits den Angeboten zugeteilt','deal')}${stat('Reserviert / verbraucht',money(used),'Cashback plus beispielhafte Gebühr','clock')}</section><div class="info-note">${icon('help')}<span>Bei der Angebotsanlage wird ein Budget aus dem Demo-Guthaben zugeteilt. Jede Dealannahme reserviert Cashback plus 10 % Beispielgebühr. Stornierungen geben die Reservierung wieder frei. Ausgezahlte Deals bleiben als verbrauchtes Budget erfasst.</span></div><section class="panel"><h2>Deine Kampagnen</h2>${os.map(o=>{const used=M.offerUsed(state,o.id),percent=Math.min(100,used/o.budget*100);return `<div class="budget-row"><div><strong>${userText(o.title)}</strong><span>${money(used)} von ${money(o.budget)} reserviert / verbraucht</span></div><div class="budget-progress"><i style="width:${percent}%"></i></div><div><small>${money(M.offerAvailable(state,o))} verfügbar</small><a href="#offer-edit:${o.id}">Budget ändern ${icon('arrow')}</a></div></div>`;}).join('')}</section>`;}
function offerForm(id){const o=id?state.offers.find(x=>x.id===id&&x.providerId===session.provider):null;if(id&&!o)return empty('Angebot nicht gefunden','Wähle eines deiner Angebote.',link('Meine Angebote','offers'));const hasDeals=o&&state.deals.some(d=>d.offerId===id);return heading(o?'Angebot bearbeiten':'Ein Angebot, das überzeugt.','Klare Konditionen, eine echte Geldprämie und ein gedecktes Budget.',link('Zurück zu Angeboten','offers','btn text'))+`<form data-form="offer" data-id="${o?.id||''}" class="offer-form-layout"><div class="panel form-panel"><h2>Was bietest du an?</h2><div class="form-grid"><label class="span-two">Angebotstitel<input name="title" required minlength="5" maxlength="100" placeholder="z. B. Glasfaser 500 mit 150 € Cashback" value="${esc(o?.title||'')}"></label><label>Hauptkategorie<select id="offer-category" name="category">${CATEGORIES.map(c=>opt(c,c,categoryName(o?.category)||CATEGORIES[0])).join('')}</select></label><label>Unterkategorie<select id="offer-subcategory" name="subcategory" ${subcategoriesFor(o?.category||CATEGORIES[0]).length?'required':'disabled'}>${subcategoryOptions(o?.category||CATEGORIES[0],o?.subcategory||'')}</select></label>${o?.purchase?`<label>Kaufpreis je Angebot (€)<input name="purchaseUnitPrice" type="number" required min="1" max="100000" step="0.01" value="${o.purchase.unitCents/100}"><input name="price" type="hidden" value="${esc(o.price)}"></label>`:`<label>Preis / Vertragskosten<input name="price" required placeholder="z. B. 39,99 € / Monat" value="${esc(o?.price||'')}"></label>`}<label class="span-two">Beschreibung<textarea name="description" required minlength="20" maxlength="2000" placeholder="Erkläre die wichtigsten Leistungen und Vorteile.">${esc(o?.description||'')}</textarea></label><label class="span-two">Bedingungen für die Geldprämie<textarea name="conditions" required minlength="15" maxlength="2000" placeholder="Was muss das Mitglied erfüllen? Wann darf die Prämie freigegeben werden?">${esc(o?.conditions||'')}</textarea></label><label>Region<input name="region" required value="${esc(o?.region||'Deutschland')}"></label><label>Angebotsende<input type="date" name="validUntil" required min="${new Date().toISOString().slice(0,10)}" value="${o?.validUntil||'2027-12-31'}"></label></div></div><aside class="panel form-panel"><div class="eyebrow">PRÄMIE & BUDGET</div><label>Cashback für das Mitglied (€)<input id="offer-cashback" name="cashback" type="number" required min="1" max="10000" step="0.01" value="${o?.cashback||100}" ${hasDeals?'readonly':''}></label>${hasDeals?'<p class="fineprint">Für Angebote mit bestehenden Deals bleibt die Prämie unverändert.</p>':''}<div class="fee-preview" id="fee-preview">${feePreview(o?.cashback||100)}</div><label>Gesamtes Angebotsbudget (€)<input name="budget" type="number" required min="1" max="1000000" step="0.01" value="${o?.budget||2000}"></label><label>Prüffrist im Testszenario (Tage)<input name="payoutDays" type="number" min="0" max="180" value="${o?.payoutDays??14}"></label><p class="fineprint">Dein freies Demo-Guthaben: <strong>${money(me().credit)}</strong>. Bei Änderungen wird nur die Budgetdifferenz verrechnet.</p><div class="info-note small-note">Neue und bearbeitete Angebote werden vor der Veröffentlichung vom Admin geprüft.</div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Zur Freigabe einreichen ${icon('arrow')}</button></aside></form>`;}
function feePreview(n){n=Number(n)||0;return `<div>Cashback für Mitglied<strong>${money(n)}</strong></div><div>Beispiel-Servicegebühr (10 %)<strong>${money(M.feeFor(n))}</strong></div><div>Reservierung pro Deal<strong>${money(n+M.feeFor(n))}</strong></div>`;}
function profileField(u,name,label,type='text',placeholder=''){return `<label>${label}<input name="${name}" type="${type}" maxlength="300" value="${esc(u[name]||'')}" placeholder="${esc(placeholder)}"></label>`;}
function profilePage(){const u=me(),member=role==='member';return heading(member?'Mein Profil':'Dein Firmenprofil','Identität, Kontakt und Anschrift für das Testszenario verwalten.')+`<div class="two-col"><form data-form="profile" class="panel form-panel"><div class="profile-head"><span class="avatar large">${initial(u.name)}</span><div><h2>${userText(u.name)}</h2><small>${u.id} · ${u.status==='active'?'Aktiv':'Gesperrt'}</small></div></div><label>${member?'Vollständiger Name':'Firmenname'}<input name="name" required minlength="3" maxlength="80" value="${esc(u.name)}"></label>${member?`<label>Stadt<input name="city" required value="${esc(u.city||'')}"></label><label>E-Mail-Adresse<input value="${esc(u.email)}" readonly></label>`:`<div class="form-grid">${profileField(u,'contactName','Ansprechpartner','text','Vor- und Nachname')}${profileField(u,'email','Kontakt-E-Mail','email','partner@example.test')}</div><label>Region<input name="region" required value="${esc(u.region)}"></label><label>Firmenbeschreibung<textarea name="description" required minlength="15" maxlength="2000">${esc(u.description)}</textarea></label>`}<h3>Kontakt & Anschrift</h3><p class="fineprint">Optionale Angaben. Bitte ausschließlich fiktive Daten für die Demo verwenden. Die Administration kann diese Stammdaten unter Konten einsehen.</p><div class="form-grid">${profileField(u,'phone','Telefonnummer','tel','Demo-Telefonnummer')}${profileField(u,'country','Land','text','z. B. Deutschland')}<label class="span-two">Straße und Hausnummer<input name="address" maxlength="300" value="${esc(u.address||'')}" placeholder="Fiktive Anschrift"></label>${profileField(u,'postalCode','Postleitzahl','text','z. B. 01234')}${!member?profileField(u,'city','Firmensitz / Ort','text','z. B. Stuttgart'):''}</div>${!member?`<h3>Unternehmensangaben</h3><div class="form-grid">${profileField(u,'legalForm','Rechtsform','text','z. B. GmbH')}${profileField(u,'registerNumber','Handelsregister / Registernummer','text','Demo-Registernummer')}${profileField(u,'vatId','USt-IdNr.','text','Demo-Angabe')}${profileField(u,'website','Website','url','https://example.test')}</div><a href="#provider:${u.id}" class="text-btn">Anbieterprofil ansehen ${icon('arrow')}</a>`:''}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Profil speichern</button></form><div class="panel"><div class="eyebrow">DEIN BUYME-KONTO</div><h2>Dein persönlicher Bereich</h2><p>Deine Deals, Nachrichten und Kontaktdaten gehören zu deinem angemeldeten Konto.</p><dl class="summary-facts"><div><dt>Kontonummer</dt><dd>${esc(u.id)}</dd></div><div><dt>Anmelde-E-Mail</dt><dd>${esc(auth.email)}</dd></div></dl><a class="btn secondary" href="#security">Passwort ändern ${icon('lock')}</a><div class="info-note">${icon('help')}<span>Konten und Änderungen werden für diesen privaten Test in deinem Browser gespeichert. Die Administration kann Stammdaten und Vorgänge zuordnen.</span></div><button class="btn text" data-action="logout">Abmelden</button></div></div>`;}
function renderModal(){const root=$('#modal-root');if(!modal){root.innerHTML='';$('#app').inert=false;document.body.classList.remove('modal-open');return;}let {type,id}=modal,content='',d=id&&state.deals.find(x=>x.id===id);const form=(kind,body,submit)=>`<form data-form="${kind}" data-id="${id||''}">${body}<div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="close-modal">Abbrechen</button><button class="btn primary" type="submit">${submit}</button></div></form>`;
 if(type==='accept'){const o=state.offers.find(x=>x.id===id);content=`<h2 id="modal-title">Deal starten</h2><p>${userText(o.title)} · ${money(o.cashback)} Cashback</p>${form('accept',`<div class="modal-note">${userText(o.conditions)}</div><label class="checkbox-label"><input type="checkbox" name="accepted" required>Ich habe die Prämienbedingungen gelesen und möchte einen Deal anlegen.</label><p class="fineprint">Es entsteht kein echter Vertrag. Der Anbieter finanziert die Prämie; BuyMe berechnet im Beispiel die Servicegebühr zusätzlich.</p>`,'Deal anlegen')}`;}
 else if(type==='proof'){content=`<h2 id="modal-title">Nachweis hinterlegen</h2><p>${id} · ${userText(d.offer)}</p>${form('proof',`<label>Bestell- oder Vertragsreferenz<textarea name="reference" required minlength="5" maxlength="500" placeholder="z. B. DEMO-Vertrag-12345">${esc(d.proof?.reference||'DEMO-Vertrag-'+id.slice(-4))}</textarea></label><div class="modal-note">Für diesen Test speichern wir eine Referenz anstelle echter Vertragsunterlagen. Der Anbieter sieht sie anschließend in seiner Dealansicht.</div>`,'Zur Prüfung einreichen')}`;}
 else if(type==='provider-accept'){content=`<h2 id="modal-title">Angebotsannahme prüfen</h2><p>${userText(d.user)} · ${userText(d.offer)} · ${money(d.cashback)} Cashback</p>${form('provider-accept',`<div class="modal-note">${userText(d.snapshot?.conditions||'Bestätigung des Abschlusses und erfüllte Prämienbedingungen.')}</div><label>Hinweis an das Mitglied<textarea name="note" maxlength="1500" placeholder="Optionaler Hinweis zur weiteren Bearbeitung"></textarea></label><p class="fineprint">Du übernimmst die Anfrage zur Bearbeitung. Der tatsächliche Abschluss wird nach Prüfung des Nachweises separat bestätigt.</p>`,'Annahme bestätigen')}`;}
 else if(type==='provider-work'){content=`<h2 id="modal-title">Deal bearbeiten</h2><p>${id} · ${userText(d.user)}</p>${form('provider-work',`<label>Bearbeitungsreferenz<input name="reference" required minlength="3" maxlength="120" value="${esc(d.providerReview?.reference||'')}" placeholder="Deine Bestell- oder Vertragsnummer"></label><label>Bearbeitungshinweis<textarea name="note" maxlength="1500" placeholder="Aktueller Stand der Bearbeitung">${esc(d.providerReview?.note||'')}</textarea></label><p class="fineprint">Referenz und Hinweis sind für das Mitglied und die Administration sichtbar. Die gespeicherten Angebotsbedingungen und die Prämie bleiben erhalten.</p>`,'Bearbeitung speichern')}`;}
 else if(type==='provider-correction'){content=`<h2 id="modal-title">Nachbesserung anfordern</h2><p>${id} · ${userText(d.user)}</p>${form('provider-correction',`<label>Was fehlt für die Prüfung?<textarea name="reason" required minlength="5" maxlength="1500" placeholder="Welche Referenz oder Ergänzung benötigst du?">${esc(d.providerReview?.correction?.status==='open'?d.providerReview.correction.text:'')}</textarea></label><p class="fineprint">Das Mitglied sieht die Rückfrage im Deal und im Chat. Die Anbieterfreigabe bleibt gesperrt, bis ein ergänzter Nachweis eingereicht wurde.</p>`,'Rückfrage senden')}`;}
 else if(type==='provider-reject'){content=`<h2 id="modal-title">Angebotsannahme ablehnen?</h2><p>${id} · ${userText(d.user)}</p>${form('provider-reject','<label>Ablehnungsgrund<textarea name="reason" required minlength="5" maxlength="1500" placeholder="Warum kann der Abschluss nicht bestätigt werden?"></textarea></label><div class="modal-note">Der Grund wird dem Mitglied angezeigt. Der Deal wird beendet, das Cashback gestoppt und die Budgetreservierung freigegeben.</div>','Begründet ablehnen')}`;}
 else if(type==='provider-confirm'){content=`<h2 id="modal-title">Abschluss prüfen & freigeben</h2><p>${userText(d.user)} · ${id}</p>${form('provider-confirm',`<div class="modal-note"><strong>Nachweis zum Abschluss</strong><p>${userText(d.proof?.reference||'Nicht vorhanden')}</p><strong>Gespeicherte Prämienbedingungen</strong><p>${userText(d.snapshot?.conditions||'Bestätigung des Abschlusses und erfüllte Prämienbedingungen.')}</p></div><label>Bearbeitungsreferenz<input name="reference" required minlength="3" maxlength="120" value="${esc(d.providerReview?.reference||'')}" placeholder="Deine Bestell- oder Vertragsnummer"></label><label>Prüfvermerk<textarea name="note" required minlength="5" maxlength="1500" placeholder="Was wurde geprüft und bestätigt?">${esc(d.providerReview?.note||'')}</textarea></label><label class="workflow-check"><input type="checkbox" name="conditionsChecked" required>Ich habe den Nachweis geprüft. Der Abschluss und die vereinbarten Prämienbedingungen sind erfüllt.</label><p class="fineprint">Die Anbieterfreigabe übergibt den Deal an BuyMe. Die Administration prüft Frist und Abschluss vor der separaten Cashback-Freigabe. Keine echte Zahlung.</p>`,'Anbieterfreigabe erteilen')}`;}
 else if(type==='cancel'){content=`<h2 id="modal-title">Deal stornieren?</h2><p>Die Budgetreservierung wird freigegeben und das Cashback gestoppt. Bei Kaufangeboten wird zusätzlich die Erstattung des Kaufpreises simuliert. Der Verlauf bleibt erhalten.</p>${form('cancel','<label>Begründung<textarea name="reason" required minlength="5" maxlength="1000" placeholder="Warum wird der Deal storniert?"></textarea></label>','Stornierung speichern')}`;}
 else if(type==='support'){content=`<h2 id="modal-title">BuyMe um Klärung bitten</h2><p>${id} · ${userText(d.offer)}</p>${form('support','<label>Betreff<input name="subject" required minlength="5" maxlength="120" placeholder="Wobei brauchst du Unterstützung?"></label><label>Deine Rückfrage<textarea name="text" required minlength="5" maxlength="3000" placeholder="Beschreibe den Sachverhalt."></textarea></label>','Rückfrage speichern')}`;}
 else if(type==='payout'){const w=M.walletSummary(state,session.member);content=`<h2 id="modal-title">Auszahlung simulieren</h2><p>Du forderst die Auszahlung von <strong>${money(w.available)}</strong> an. Alle freigegebenen Prämien wechseln in „In Auszahlung“.</p>${form('payout','<div class="modal-note">Der Admin kann anschließend den Zahlungseingang oder einen Fehler simulieren. Es wird keine echte Bankverbindung benötigt und kein Geld überwiesen.</div>','Auszahlung anfordern')}`;}
 else if(type==='topup'){content=`<h2 id="modal-title">Demo-Guthaben aufladen</h2><p>Mit zusätzlichem Demo-Guthaben kannst du neue Angebotsbudgets finanzieren.</p>${form('topup','<label>Betrag (€)<input name="amount" type="number" min="10" max="100000" step="0.01" required value="2500"></label><div class="modal-note">Reine Simulation. Keine Zahlung und keine Rechnung.</div>','Guthaben simulieren')}`;}
 else{content='<h2 id="modal-title">BuyMe</h2><p>Bitte wähle eine Aktion aus deinem Bereich.</p>';}
 root.innerHTML=`<div class="modal-backdrop" data-action="close-modal"></div><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="close-btn" data-action="close-modal" aria-label="Dialog schließen">${icon('close')}</button>${content}</section>`;$('#app').inert=true;document.body.classList.add('modal-open');}
function openModal(type,id=null){lastFocus=document.activeElement?.id||null;modal={type,id};renderModal();requestAnimationFrame(()=>$('.modal')?.focus());}
function closeModal(){modal=null;renderModal();if(lastFocus)document.getElementById(lastFocus)?.focus();}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
function run(fn,message){try{fn();persist();render();if(message)toast(message);}catch(err){toast(err.message);}}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'market';dealTab='overview';modal=null;render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===Auth.AUTH_SESSION_KEY){state=loadState();render();}});
window.addEventListener('pageshow',e=>{if(e.persisted){state=loadState();render();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)closeModal();if(e.key==='Tab'&&modal){const els=[...$('.modal').querySelectorAll('button:not([disabled]),input,textarea,select,a[href]')].filter(el=>el.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function clickHandler(e){const b=e.target.closest('button,a');if(!b||b.disabled)return;if(b.dataset.role){switchRole(b.dataset.role);return;}if(b.dataset.category!==undefined){filter.category=b.dataset.category;filter.subcategory='';render();$('#market-results')?.scrollIntoView({behavior:'smooth',block:'start'});return;}if(b.dataset.subcategory!==undefined){filter.subcategory=b.dataset.subcategory;render();$('#market-results')?.scrollIntoView({behavior:'smooth',block:'start'});return;}if(b.dataset.tab){dealTab=b.dataset.tab;render();return;}if(b.dataset.thread){selectedThread=b.dataset.thread;render();return;}if(b.dataset.messageMode){messageMode=b.dataset.messageMode;render();return;}if(b.dataset.providerScope){providerScope=b.dataset.providerScope;render();return;}const a=b.dataset.action,id=b.dataset.id;
 if(b.dataset.password){const input=document.getElementById(b.dataset.password);input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Anzeigen':'Verbergen';b.setAttribute('aria-label',input.type==='password'?'Passwort anzeigen':'Passwort verbergen');return;}
 if(!a)return;
 if(a==='logout'){Auth.clearAuth();auth=null;role=null;session={};modal=null;drafts={};reviewSaved=null;checkoutDraft={};checkoutFailed=false;selectedThread='';route='market';history.replaceState(null,'','#market');render();toast('Du bist abgemeldet.');return;}
 if(a==='test-login'){if(auth){toast('Bitte zuerst abmelden, um ein anderes Konto zu testen.');return;}loginEmail=b.dataset.email;go('login');return;}
 if(a==='login-to-deal'){requireLogin('offer:'+id);return;}
 if(a==='help'){go('how');return;}
 if(['register','register-provider'].includes(a)){go(a);return;}
 if(['accept','proof','provider-confirm','provider-accept','provider-work','provider-correction','provider-reject','cancel','support','review','payout','topup','fund-deal','toggle-offer'].includes(a)&&!auth){requireLogin();return;}

 if(a==='review'){if(!myDeals().some(d=>d.id===id)){toast('Deal nicht verfügbar');return;}dealTab='reviews';route='deal:'+id;history.replaceState(null,'','#'+route);render();requestAnimationFrame(()=>document.getElementById('review-entry')?.scrollIntoView({behavior:'smooth',block:'start'}));return;}
 if(['accept','proof','provider-confirm','provider-accept','provider-work','provider-correction','provider-reject','cancel','support','payout','topup'].includes(a)){openModal(a,id);return;}
 if(a==='toggle-categories'){categoriesExpanded=!categoriesExpanded;render();document.getElementById('category-toggle')?.focus();return;}
 if(a==='scroll-offers')$('#market-results')?.scrollIntoView({behavior:'smooth',block:'start'});if(a==='close-modal')closeModal();if(a==='clear-filters'){filter={q:'',category:'',subcategory:'',region:'',min:'',sort:'recommended'};render();}
 if(a==='fund-deal')run(()=>M.fundExistingDeal(state,id,session.provider),'Budgetdeckung im Deal bestätigt.');
 if(a==='toggle-offer')run(()=>M.toggleOffer(state,id,session.provider),'Angebotsstatus aktualisiert.');
 if(a==='receipt'){const d=myDeals().find(x=>x.id===id&&x.payment==='paid');if(d)download('BuyMe_Demobeleg_'+d.id+'.txt',`BUYME · DEMO-AUSZAHLUNGSBELEG\n\nDeal: ${d.id}\nMitglied: ${d.user}\nAnbieter: ${d.provider}\nAngebot: ${d.offer}\nPrämie: ${money(d.cashback)}\nStatus: ${PL[d.payment]}\nZahlungsreferenz: ${d.paymentRef}\n\nFiktiver Testbeleg. Keine echte Zahlung, keine Rechnung.`);}
 if(a==='export'){try{download('BuyMe_Eigene_Testdaten.json',JSON.stringify(participantDataExport(state,auth),null,2),'application/json');}catch(err){toast(err.message);}}
}
document.addEventListener('click',clickHandler);
document.addEventListener('click',e=>{if(e.target.matches('.modal-backdrop'))closeModal();});
document.addEventListener('input',e=>{const id=e.target.id;if(id==='offer-search'){filter.q=e.target.value;render();}if(id==='region-search'){filter.region=e.target.value;render();}if(id==='deal-search'){dealSearch=e.target.value;render();}if(id==='offer-cashback')$('#fee-preview').innerHTML=feePreview(e.target.value);if(e.target.closest('[data-form="direct"]'))drafts['direct-'+e.target.closest('form').dataset.id]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='category-filter'){filter.category=e.target.value;filter.subcategory='';render();}if(e.target.id==='subcategory-filter'){filter.subcategory=e.target.value;render();}if(e.target.id==='offer-category'){const select=$('#offer-subcategory'),has=subcategoriesFor(e.target.value).length>0;select.innerHTML=subcategoryOptions(e.target.value,'',false);select.disabled=!has;select.required=has;}if(e.target.id==='offer-sort'){filter.sort=e.target.value;render();}if(e.target.id==='deal-filter'){dealFilter=e.target.value;render();}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form||['cart-add','purchase-checkout'].includes(f.dataset.form))return;e.preventDefault();const data=Object.fromEntries(new FormData(f)),kind=f.dataset.form,id=f.dataset.id;let target=null,message='Gespeichert.';
 if(kind.startsWith('auth-')){const submit=f.querySelector('button[type="submit"]');if(submit.disabled)return;submit.disabled=true;submit.setAttribute('aria-busy','true');const err=f.querySelector('.form-error');err.textContent='';try{state=loadState();if(kind==='auth-login'){const user=await Auth.authenticate(state,data.email,data.password);Auth.saveAuth(user,data.remember==='on');afterLogin();toast('Willkommen bei BuyMe.');}else if(kind==='auth-register'){const user=await Auth.registerAccount(state,data);saveState(state);Auth.saveAuth(user);afterLogin();toast(user.role==='provider'?'Konto erstellt. Dein Anbieterprofil wartet auf Prüfung.':'Willkommen! Dein Mitgliedskonto ist erstellt.');}else if(kind==='auth-password'){const user=Auth.currentAuth(state);if(!user)throw Error('Bitte melde dich erneut an.');await Auth.changePassword(state,user,data);saveState(state);f.reset();toast('Dein Passwort wurde geändert.');}}catch(error){err.textContent=error.message;err.focus();}finally{if(submit.isConnected){submit.disabled=false;submit.removeAttribute('aria-busy');}}return;}
 try{state=loadState();syncAuth();if(!auth||!['member','provider'].includes(role))throw Error('Bitte melde dich mit deinem Konto an.');
 if(kind==='accept'){const d=M.acceptOffer(state,id,session.member);target='deal:'+d.id;message='Deal angelegt. Der Anbieter kann die Annahme prüfen. Hinterlege deinen Nachweis.';}
 if(kind==='proof'){M.attachProof(state,id,session.member,data.reference);message='Nachweis hinterlegt. Der Anbieter kann jetzt prüfen.';}
 if(kind==='provider-accept'){M.acceptProviderDeal(state,id,session.provider,data.note);message='Angebotsannahme bestätigt. Der Deal ist in Bearbeitung.';}
 if(kind==='provider-work'){M.saveProviderWork(state,id,session.provider,data);message='Bearbeitung gespeichert und im Deal sichtbar.';}
 if(kind==='provider-correction'){M.requestProviderCorrection(state,id,session.provider,data.reason);message='Rückfrage an das Mitglied im Deal gespeichert.';}
 if(kind==='provider-reject'){M.rejectProviderDeal(state,id,session.provider,data.reason);message='Annahme begründet abgelehnt. Cashback gestoppt.';}
 if(kind==='provider-confirm'){M.confirmProviderDeal(state,id,session.provider,data);message='Anbieterfreigabe dokumentiert. BuyMe prüft Abschluss und Cashback.';}
 if(kind==='cancel'){M.cancelMemberDeal(state,id,session.member,data.reason);message='Deal storniert. Die Budgetreservierung ist wieder frei.';}
 if(kind==='support'){M.openSupport(state,id,role,me().id,data.subject,data.text);dealTab='support';message='Rückfrage im Admin Cockpit hinterlegt.';}
 if(kind==='support-reply'){M.replySupport(state,id,role,me().id,data.text);message='Antwort an BuyMe gespeichert.';}
 if(kind==='direct'){M.sendDirect(state,id,role,me().id,data.text);drafts['direct-'+id]='';message='Demo-Nachricht gespeichert.';}
 if(kind==='payout'){M.requestPayout(state,session.member);message='Demo-Auszahlung angefordert. Im Admin kann sie abgeschlossen werden.';}
 if(kind==='topup'){M.topUp(state,session.provider,data.amount);message='Demo-Guthaben aufgeladen.';}
 if(kind==='review-entry'){reviewSaved=submitReviewEntry(state,role,me().id,data);drafts['review-entry']={};dealTab='reviews';message='Bewertung gespeichert und für beide Dealparteien sichtbar.';}
 if(kind==='profile'){M.updateProfile(state,role,me().id,data);message='Profil aktualisiert. Bestehende Dealvereinbarungen bleiben erhalten.';}
 if(kind==='offer'){const o=M.createOffer(state,session.provider,data,id||null);target='offers';message='Angebot '+o.id+' wartet jetzt im Admin auf Freigabe.';}
 persist();modal=null;if(target){route=target;history.replaceState(null,'','#'+target);}render();toast(message);
 }catch(err){const error=f.querySelector('.form-error');if(error){error.textContent=err.message;error.focus?.();}else toast(err.message);}
});
async function boot(){try{if(await Auth.initializeAuth(state))saveState(state);syncAuth();render();}catch(error){$('#app').innerHTML=`<main class="panel auth-panel"><h1>Anmeldung nicht verfügbar</h1><p>${esc(error.message)}</p><p>Deine bisherigen Testdaten bleiben erhalten.</p></main>`;}}
boot();

function reviewsPage(){const rows=M.visibleReviews(state,role,me().id),received=rows.filter(r=>M.reviewTargetRole(r)===role),given=rows.filter(r=>M.reviewAuthorRole(r)===role);return heading('Meine Bewertungen','Deine Erfahrungen und die Bewertungen deiner Dealpartner an einem Ort.')+reviewEntry(state,role,me().id,{draft:drafts['review-entry']||{},saved:reviewSaved})+`<section class="review-center-section"><h2>Erhaltene Bewertungen</h2><div class="deal-review-grid">${received.map(r=>reviewCard(state,r)).join('')||'<p class="muted">Du hast noch keine Bewertungen erhalten.</p>'}</div></section><section class="review-center-section"><h2>Abgegebene Bewertungen</h2><div class="deal-review-grid">${given.map(r=>reviewCard(state,r)).join('')||'<p class="muted">Du hast noch keine Bewertungen abgegeben.</p>'}</div></section>`;}
installReviewEntryInteractions(document,values=>{drafts['review-entry']=values;});

installCommerceInteractions(document,{
 context:()=>{state=loadState();syncAuth();return {state,role,owner:cartOwner(),token:checkoutToken()};},
 draft:values=>{checkoutDraft={...values,token:checkoutDraft.token};},
 changed:(kind,result)=>{persist();if(kind==='purchase-checkout'){checkoutFailed=result.status==='failed';checkoutDraft={...checkoutDraft,token:null};if(result.status==='paid'){checkoutDraft={};route='order:'+result.id;history.replaceState(null,'','#'+route);}render();window.scrollTo(0,0);toast(result.status==='paid'?'Testzahlung erfolgreich. Bestellung und Deals angelegt.':'Testzahlung fehlgeschlagen. Warenkorb bleibt erhalten.');}else{checkoutDraft={...checkoutDraft,token:null,accepted:false};checkoutFailed=false;if(kind==='cart-add'){route='cart';history.replaceState(null,'','#cart');}render();toast(kind==='cart-add'?'Zum Warenkorb hinzugefügt.':'Warenkorb aktualisiert.');}},
 error:err=>toast(err.message)
});

installLegalInteractions({getState:()=>state,getActor:()=>Auth.currentAuth(state),save:()=>saveState(state),refresh:render,go});
